import { useEffect, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Award, Bell, BookOpen, Calendar, CheckCircle2, Edit, Eye, GraduationCap, Home, Mail, Menu, PanelLeft, Plus, Save, Trash2, UserPlus, X, FileText } from 'lucide-react'
import { profileApi, teachersApi, subjectsApi } from '@/lib/api'
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Progress } from "@/components/ui/progress"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"

// Mock API (substitua pelos imports reais da sua aplicação)
const API_BASE = "http://localhost:5000/api"
const getToken = () => localStorage.getItem("auth_token")

const api = {
  async fetchWithAuth(endpoint: string, options: any = {}) {
    const res = await fetch(`${API_BASE}${endpoint}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${getToken()}`,
        ...options.headers,
      },
    })
    if (!res.ok) throw new Error(`Erro ${res.status}`)
    if (res.status === 204) return null
    return res.json()
  },
}

const sidebarItems = [
  { title: "Painel", icon: <Home />, value: "painel" },
  { title: "Aulas", icon: <BookOpen />, value: "aulas" },
  { title: "Professores", icon: <UserPlus />, value: "professores" },
  { title: "Anotações", icon: <FileText />, value: "anotacoes" },
  { title: "Perfil", icon: <GraduationCap />, value: "perfil" },
]

const COLORS = [
  { label: "Azul", value: "bg-blue-500" },
  { label: "Verde", value: "bg-green-500" },
  { label: "Roxo", value: "bg-purple-500" },
  { label: "Rosa", value: "bg-pink-500" },
  { label: "Amarelo", value: "bg-yellow-500" },
  { label: "Vermelho", value: "bg-red-500" },
]

export default function DashboardPage() {
  const [activeTab, setActiveTab] = useState("painel")
  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  const [teachers, setTeachers] = useState([])
  const [subjects, setSubjects] = useState([])
  const [notes, setNotes] = useState([])
  const [student, setStudent] = useState(null)
  const [stats, setStats] = useState(null)
  const [loading, setLoading] = useState(true)

  // Modals
  const [teacherModal, setTeacherModal] = useState(false)
  const [subjectModal, setSubjectModal] = useState(false)
  const [noteModal, setNoteModal] = useState(false)
  const [editingTeacher, setEditingTeacher] = useState(null)
  const [editingSubject, setEditingSubject] = useState(null)
  const [editingNote, setEditingNote] = useState(null)

  // Form states
  const [teacherForm, setTeacherForm] = useState({ nome: "", email: "", disciplina: "" })
  const [subjectForm, setSubjectForm] = useState({ 
    nome: "", 
    cor: "bg-blue-500", 
    professorId: "", 
    notaProva: "",
    trabalhos: [] 
  })
  const [noteForm, setNoteForm] = useState({ titulo: "", conteudo: "", materiaId: "none" })
  const [profileForm, setProfileForm] = useState({ nome: "", email: "", telefone: "" })
  const [profileEditing, setProfileEditing] = useState(false)

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    try {
      setLoading(true)
      
      // Carregar dados do dashboard
      const dashboard = await api.fetchWithAuth("/Dashboard")
      const professores = await api.fetchWithAuth("/Professores")
      const materias = await api.fetchWithAuth("/Materias")
      const anotacoes = await api.fetchWithAuth("/Anotacoes")
      const perfil = await api.fetchWithAuth("/Usuarios/perfil")

      setTeachers(professores || [])
      setSubjects(materias || [])
      setNotes(anotacoes || [])
      setStudent(perfil)
      setProfileForm({ 
        nome: perfil?.nome || "", 
        email: perfil?.email || "", 
        telefone: perfil?.telefone || "" 
      })

      if (dashboard) {
        setStats(dashboard.metricasProgresso)
      }
    } catch (error) {
      console.error("Erro ao carregar dados:", error)
    } finally {
      setLoading(false)
    }
  }

  // ============= TEACHER CRUD =============
  const openTeacherModal = (teacher = null) => {
    if (teacher) {
      setEditingTeacher(teacher)
      setTeacherForm({ 
        nome: teacher.nome, 
        email: teacher.email, 
        disciplina: teacher.disciplina || "" 
      })
    } else {
      setEditingTeacher(null)
      setTeacherForm({ nome: "", email: "", disciplina: "" })
    }
    setTeacherModal(true)
  }

  const saveTeacher = async () => {
    try {
      if (!teacherForm.nome || !teacherForm.email) {
        alert("Nome e email são obrigatórios")
        return
      }

      if (editingTeacher) {
        await api.fetchWithAuth(`/Professores/${editingTeacher.id}`, {
          method: "PUT",
          body: JSON.stringify({
            id: editingTeacher.id,
            ...teacherForm
          }),
        })
      } else {
        await api.fetchWithAuth("/Professores", {
          method: "POST",
          body: JSON.stringify(teacherForm),
        })
      }

      await loadData()
      setTeacherModal(false)
      setTeacherForm({ nome: "", email: "", disciplina: "" })
    } catch (error) {
      console.error("Erro ao salvar professor:", error)
      alert("Erro ao salvar professor")
    }
  }

  const deleteTeacher = async (id) => {
    if (!confirm("Deseja realmente excluir este professor?")) return

    try {
      await api.fetchWithAuth(`/Professores/${id}`, { method: "DELETE" })
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar professor:", error)
      alert("Erro ao deletar professor")
    }
  }

  // ============= SUBJECT CRUD =============
  const openSubjectModal = (subject = null) => {
    if (subject) {
      setEditingSubject(subject)
      setSubjectForm({
        nome: subject.nome,
        cor: subject.cor,
        professorId: subject.professorId?.toString() || "",
        notaProva: subject.notaProva?.toString() || "0",
        trabalhos: subject.trabalhos || []
      })
    } else {
      setEditingSubject(null)
      setSubjectForm({ 
        nome: "", 
        cor: "bg-blue-500", 
        professorId: "", 
        notaProva: "0",
        trabalhos: []
      })
    }
    setSubjectModal(true)
  }

  const addTrabalho = () => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: [
        ...prev.trabalhos,
        {
          titulo: "",
          descricao: "",
          dataEntrega: new Date().toISOString().split('T')[0],
          concluido: false
        }
      ]
    }))
  }

  const removeTrabalho = (index) => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: prev.trabalhos.filter((_, i) => i !== index)
    }))
  }

  const updateTrabalho = (index, field, value) => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: prev.trabalhos.map((t, i) => 
        i === index ? { ...t, [field]: value } : t
      )
    }))
  }

  const saveSubject = async () => {
    try {
      if (!subjectForm.nome || !subjectForm.professorId) {
        alert("Nome da matéria e professor são obrigatórios")
        return
      }

      const payload = {
        nome: subjectForm.nome,
        cor: subjectForm.cor,
        professorId: parseInt(subjectForm.professorId),
        notaProva: parseFloat(subjectForm.notaProva) || 0
      }

      let materiaId

      if (editingSubject) {
        await api.fetchWithAuth(`/Materias/${editingSubject.id}`, {
          method: "PUT",
          body: JSON.stringify({ id: editingSubject.id, ...payload }),
        })
        materiaId = editingSubject.id

        // Deletar trabalhos antigos e criar novos
        if (editingSubject.trabalhos) {
          for (const trabalho of editingSubject.trabalhos) {
            await api.fetchWithAuth(`/Materias/${materiaId}/trabalhos/${trabalho.id}`, {
              method: "DELETE"
            })
          }
        }
      } else {
        const result = await api.fetchWithAuth("/Materias", {
          method: "POST",
          body: JSON.stringify(payload),
        })
        materiaId = result.id
      }

      // Criar trabalhos
      for (const trabalho of subjectForm.trabalhos) {
        if (trabalho.titulo.trim()) {
          await api.fetchWithAuth(`/Materias/${materiaId}/trabalhos`, {
            method: "POST",
            body: JSON.stringify({
              titulo: trabalho.titulo,
              descricao: trabalho.descricao || null,
              dataEntrega: new Date(trabalho.dataEntrega).toISOString(),
              concluido: trabalho.concluido
            }),
          })
        }
      }

      await loadData()
      setSubjectModal(false)
      setSubjectForm({ nome: "", cor: "bg-blue-500", professorId: "", notaProva: "0", trabalhos: [] })
    } catch (error) {
      console.error("Erro ao salvar matéria:", error)
      alert("Erro ao salvar matéria")
    }
  }

  const deleteSubject = async (id) => {
    if (!confirm("Deseja realmente excluir esta matéria?")) return

    try {
      await api.fetchWithAuth(`/Materias/${id}`, { method: "DELETE" })
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar matéria:", error)
      alert("Erro ao deletar matéria")
    }
  }

  // ============= NOTE CRUD =============
  const openNoteModal = (note = null) => {
    if (note) {
      setEditingNote(note)
      setNoteForm({ 
        titulo: note.titulo, 
        conteudo: note.conteudo, 
        materiaId: note.materiaId?.toString() || "none" 
      })
    } else {
      setEditingNote(null)
      setNoteForm({ titulo: "", conteudo: "", materiaId: "none" })
    }
    setNoteModal(true)
  }

  const saveNote = async () => {
    try {
      if (!noteForm.titulo || !noteForm.conteudo) {
        alert("Título e conteúdo são obrigatórios")
        return
      }

      const payload = {
        titulo: noteForm.titulo,
        conteudo: noteForm.conteudo,
        materiaId: noteForm.materiaId === "none" ? null : parseInt(noteForm.materiaId)
      }

      if (editingNote) {
        await api.fetchWithAuth(`/Anotacoes/${editingNote.id}`, {
          method: "PUT",
          body: JSON.stringify({ id: editingNote.id, ...payload }),
        })
      } else {
        await api.fetchWithAuth("/Anotacoes", {
          method: "POST",
          body: JSON.stringify(payload),
        })
      }

      await loadData()
      setNoteModal(false)
      setNoteForm({ titulo: "", conteudo: "", materiaId: "none" })
    } catch (error) {
      console.error("Erro ao salvar anotação:", error)
      alert("Erro ao salvar anotação")
    }
  }

  const deleteNote = async (id) => {
    if (!confirm("Deseja realmente excluir esta anotação?")) return

    try {
      await api.fetchWithAuth(`/Anotacoes/${id}`, { method: "DELETE" })
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar anotação:", error)
      alert("Erro ao deletar anotação")
    }
  }

  // ============= PROFILE =============
  const saveProfile = async () => {
    try {
      await api.fetchWithAuth("/Usuarios/perfil", {
        method: "PUT",
        body: JSON.stringify({
          nome: profileForm.nome,
          telefone: profileForm.telefone || null
        }),
      })

      await loadData()
      setProfileEditing(false)
      alert("Perfil atualizado com sucesso!")
    } catch (error) {
      console.error("Erro ao salvar perfil:", error)
      alert("Erro ao salvar perfil")
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <div className="text-center space-y-4">
          <GraduationCap className="h-16 w-16 mx-auto animate-pulse text-primary" />
          <p className="text-lg text-muted-foreground">Carregando dashboard...</p>
        </div>
      </div>
    )
  }

  const calculateScore = () => {
    if (stats) return Math.round(stats.pontuacaoGeral)
    return 0
  }

  return (
    <div className="relative min-h-screen overflow-hidden bg-background">
      {/* Sidebar */}
      <div className={cn(
        "fixed inset-y-0 left-0 z-30 hidden w-64 transform border-r bg-background transition-transform duration-300 ease-in-out md:block",
        sidebarOpen ? "translate-x-0" : "-translate-x-full"
      )}>
        <div className="flex h-full flex-col">
          <div className="p-4">
            <div className="flex items-center gap-3">
              <div className="flex aspect-square size-10 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-600 to-purple-600 text-white">
                <GraduationCap className="size-5" />
              </div>
              <div>
                <h2 className="font-semibold">Zoombi</h2>
                <p className="text-xs text-muted-foreground">Organize seus estudos</p>
              </div>
            </div>
          </div>

          <ScrollArea className="flex-1 px-3 py-2">
            <div className="space-y-1">
              {sidebarItems.map((item) => (
                <button
                  key={item.value}
                  onClick={() => setActiveTab(item.value)}
                  className={cn(
                    "flex w-full items-center gap-3 rounded-2xl px-3 py-2 text-sm font-medium",
                    activeTab === item.value ? "bg-primary/10 text-primary" : "hover:bg-muted"
                  )}
                >
                  {item.icon}
                  <span>{item.title}</span>
                </button>
              ))}
            </div>
          </ScrollArea>
        </div>
      </div>

      {/* Main Content */}
      <div className={cn("min-h-screen transition-all duration-300 ease-in-out", sidebarOpen ? "md:pl-64" : "md:pl-0")}>
        <header className="sticky top-0 z-10 flex h-16 items-center gap-3 border-b bg-background/95 px-4 backdrop-blur">
          <Button variant="ghost" size="icon" className="hidden md:flex" onClick={() => setSidebarOpen(!sidebarOpen)}>
            <PanelLeft className="h-5 w-5" />
          </Button>
          <div className="flex flex-1 items-center justify-between">
            <h1 className="text-xl font-semibold">Olá, {student?.nome || "Estudante"}!</h1>
          </div>
        </header>

        <main className="flex-1 p-4 md:p-6">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="grid w-full max-w-[600px] grid-cols-5 rounded-2xl p-1">
              <TabsTrigger value="painel">Painel</TabsTrigger>
              <TabsTrigger value="aulas">Aulas</TabsTrigger>
              <TabsTrigger value="professores">Professores</TabsTrigger>
              <TabsTrigger value="anotacoes">Anotações</TabsTrigger>
              <TabsTrigger value="perfil">Perfil</TabsTrigger>
            </TabsList>

            {/* PAINEL */}
            <TabsContent value="painel" className="space-y-8 mt-8">
              <Card className="bg-gradient-to-r from-blue-600 to-purple-600 text-white">
                <CardHeader>
                  <CardTitle className="text-2xl">Dashboard</CardTitle>
                  <CardDescription className="text-white/80">
                    Acompanhe seu progresso acadêmico
                  </CardDescription>
                </CardHeader>
              </Card>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Frequência</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="text-3xl font-bold">{stats?.frequenciaGeral || 0}%</div>
                    <Progress value={stats?.frequenciaGeral || 0} className="mt-2" />
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Trabalhos</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="text-3xl font-bold">{stats?.percentualTrabalhos || 0}%</div>
                    <Progress value={stats?.percentualTrabalhos || 0} className="mt-2" />
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Pontuação</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="text-3xl font-bold">{calculateScore()}/100</div>
                    <Progress value={calculateScore()} className="mt-2" />
                  </CardContent>
                </Card>
              </div>
            </TabsContent>

            {/* AULAS */}
            <TabsContent value="aulas" className="space-y-8 mt-8">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold">Minhas Aulas</h2>
                <Button onClick={() => openSubjectModal()}>
                  <Plus className="mr-2 h-4 w-4" />
                  Nova Matéria
                </Button>
              </div>

              <div className="grid gap-4">
                {subjects.map((subject) => (
                  <Card key={subject.id}>
                    <CardHeader>
                      <div className="flex justify-between items-start">
                        <div>
                          <CardTitle>{subject.nome}</CardTitle>
                          <CardDescription>
                            Professor: {teachers.find(t => t.id === subject.professorId)?.nome || "N/A"}
                          </CardDescription>
                        </div>
                        <Badge>Nota: {subject.notaProva || 0}</Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        <div>
                          <div className="flex justify-between text-sm">
                            <span>Frequência</span>
                            <span>{subject.aulas?.filter(a => a.presente).length || 0}/{subject.aulas?.length || 0}</span>
                          </div>
                          <Progress 
                            value={subject.aulas?.length ? (subject.aulas.filter(a => a.presente).length / subject.aulas.length * 100) : 0} 
                            className="mt-1"
                          />
                        </div>
                        <div>
                          <div className="flex justify-between text-sm">
                            <span>Trabalhos</span>
                            <span>{subject.trabalhos?.filter(t => t.concluido).length || 0}/{subject.trabalhos?.length || 0}</span>
                          </div>
                          <Progress 
                            value={subject.trabalhos?.length ? (subject.trabalhos.filter(t => t.concluido).length / subject.trabalhos.length * 100) : 0}
                            className="mt-1"
                          />
                        </div>
                      </div>
                    </CardContent>
                    <CardFooter className="flex gap-2">
                      <Button variant="outline" size="sm" onClick={() => openSubjectModal(subject)}>
                        <Edit className="mr-2 h-4 w-4" />
                        Editar
                      </Button>
                      <Button variant="outline" size="sm" className="text-red-500" onClick={() => deleteSubject(subject.id)}>
                        <Trash2 className="mr-2 h-4 w-4" />
                        Excluir
                      </Button>
                    </CardFooter>
                  </Card>
                ))}
              </div>
            </TabsContent>

            {/* PROFESSORES */}
            <TabsContent value="professores" className="space-y-8 mt-8">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold">Meus Professores</h2>
                <Button onClick={() => openTeacherModal()}>
                  <UserPlus className="mr-2 h-4 w-4" />
                  Adicionar Professor
                </Button>
              </div>

              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {teachers.map((teacher) => (
                  <Card key={teacher.id}>
                    <CardHeader>
                      <div className="flex items-center gap-3">
                        <Avatar>
                          <AvatarFallback>{teacher.nome?.charAt(0) || "?"}</AvatarFallback>
                        </Avatar>
                        <div>
                          <CardTitle className="text-lg">{teacher.nome}</CardTitle>
                          <CardDescription>{teacher.disciplina}</CardDescription>
                        </div>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Mail className="h-4 w-4" />
                        <span>{teacher.email}</span>
                      </div>
                    </CardContent>
                    <CardFooter className="flex gap-2">
                      <Button variant="outline" size="sm" className="flex-1" onClick={() => openTeacherModal(teacher)}>
                        <Edit className="mr-2 h-4 w-4" />
                        Editar
                      </Button>
                      <Button variant="outline" size="sm" className="text-red-500" onClick={() => deleteTeacher(teacher.id)}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </CardFooter>
                  </Card>
                ))}
              </div>
            </TabsContent>

            {/* ANOTAÇÕES */}
            <TabsContent value="anotacoes" className="space-y-8 mt-8">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold">Minhas Anotações</h2>
                <Button onClick={() => openNoteModal()}>
                  <Plus className="mr-2 h-4 w-4" />
                  Nova Anotação
                </Button>
              </div>

              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {notes.map((note) => (
                  <Card key={note.id}>
                    <CardHeader>
                      <CardTitle className="text-lg">{note.titulo}</CardTitle>
                      <CardDescription>
                        {subjects.find(s => s.id === note.materiaId)?.nome || "Geral"}
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <p className="text-sm text-muted-foreground line-clamp-3">{note.conteudo}</p>
                    </CardContent>
                    <CardFooter className="flex gap-2">
                      <Button variant="outline" size="sm" className="flex-1" onClick={() => openNoteModal(note)}>
                        <Edit className="mr-2 h-4 w-4" />
                        Editar
                      </Button>
                      <Button variant="outline" size="sm" className="text-red-500" onClick={() => deleteNote(note.id)}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </CardFooter>
                  </Card>
                ))}
              </div>
            </TabsContent>

            {/* PERFIL */}
            <TabsContent value="perfil" className="space-y-8 mt-8">
              <Card>
                <CardHeader>
                  <CardTitle>Informações Pessoais</CardTitle>
                  <CardDescription>Gerencie suas informações</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2">
                    <Label>Nome Completo</Label>
                    <Input 
                      value={profileForm.nome} 
                      onChange={(e) => setProfileForm({...profileForm, nome: e.target.value})}
                      disabled={!profileEditing}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Email</Label>
                    <Input value={profileForm.email} disabled />
                  </div>
                  <div className="space-y-2">
                    <Label>Telefone</Label>
                    <Input 
                      value={profileForm.telefone} 
                      onChange={(e) => setProfileForm({...profileForm, telefone: e.target.value})}
                      disabled={!profileEditing}
                      placeholder="(11) 99999-9999"
                    />
                  </div>
                </CardContent>
                <CardFooter className="flex gap-2">
                  {!profileEditing ? (
                    <Button onClick={() => setProfileEditing(true)}>
                      <Edit className="mr-2 h-4 w-4" />
                      Editar Perfil
                    </Button>
                  ) : (
                    <>
                      <Button variant="outline" onClick={() => {
                        setProfileEditing(false)
                        setProfileForm({
                          nome: student?.nome || "",
                          email: student?.email || "",
                          telefone: student?.telefone || ""
                        })
                      }}>
                        Cancelar
                      </Button>
                      <Button onClick={saveProfile}>
                        <Save className="mr-2 h-4 w-4" />
                        Salvar Alterações
                      </Button>
                    </>
                  )}
                </CardFooter>
              </Card>
            </TabsContent>
          </Tabs>
        </main>
      </div>

      {/* Modal Professor */}
      <Dialog open={teacherModal} onOpenChange={setTeacherModal}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>{editingTeacher ? "Editar Professor" : "Adicionar Professor"}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Nome *</Label>
              <Input 
                value={teacherForm.nome} 
                onChange={(e) => setTeacherForm({...teacherForm, nome: e.target.value})}
                placeholder="Nome do professor"
              />
            </div>
            <div className="space-y-2">
              <Label>Disciplina</Label>
              <Input 
                value={teacherForm.disciplina} 
                onChange={(e) => setTeacherForm({...teacherForm, disciplina: e.target.value})}
                placeholder="Matéria que leciona"
              />
            </div>
            <div className="space-y-2">
              <Label>Email *</Label>
              <Input 
                type="email"
                value={teacherForm.email} 
                onChange={(e) => setTeacherForm({...teacherForm, email: e.target.value})}
                placeholder="email@exemplo.com"
              />
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setTeacherModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveTeacher}>
              <Save className="mr-2 h-4 w-4" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Matéria */}
      <Dialog open={subjectModal} onOpenChange={setSubjectModal}>
        <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingSubject ? "Editar Matéria" : "Adicionar Matéria"}</DialogTitle>
            <DialogDescription>
              Preencha as informações da matéria, incluindo nota e trabalhos
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-6 py-4">
            {/* Informações Básicas */}
            <div className="space-y-4">
              <h3 className="font-semibold">Informações Básicas</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Nome da Matéria *</Label>
                  <Input 
                    value={subjectForm.nome} 
                    onChange={(e) => setSubjectForm({...subjectForm, nome: e.target.value})}
                    placeholder="Ex: Matemática"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Professor *</Label>
                  <Select 
                    value={subjectForm.professorId} 
                    onValueChange={(value) => setSubjectForm({...subjectForm, professorId: value})}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione o professor" />
                    </SelectTrigger>
                    <SelectContent>
                      {teachers.map((teacher) => (
                        <SelectItem key={teacher.id} value={teacher.id.toString()}>
                          {teacher.nome}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Cor da Matéria</Label>
                  <Select 
                    value={subjectForm.cor} 
                    onValueChange={(value) => setSubjectForm({...subjectForm, cor: value})}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Cor" />
                    </SelectTrigger>
                    <SelectContent>
                      {COLORS.map((color) => (
                        <SelectItem key={color.value} value={color.value}>
                          <div className="flex items-center gap-2">
                            <div className={cn("w-4 h-4 rounded-full", color.value)} />
                            {color.label}
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Nota da Prova</Label>
                  <Input 
                    type="number"
                    min="0"
                    max="10"
                    step="0.1"
                    value={subjectForm.notaProva} 
                    onChange={(e) => setSubjectForm({...subjectForm, notaProva: e.target.value})}
                    placeholder="0.0"
                  />
                </div>
              </div>
            </div>

            {/* Trabalhos */}
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <h3 className="font-semibold">Trabalhos</h3>
                <Button type="button" variant="outline" size="sm" onClick={addTrabalho}>
                  <Plus className="mr-2 h-4 w-4" />
                  Adicionar Trabalho
                </Button>
              </div>

              {subjectForm.trabalhos.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  Nenhum trabalho adicionado
                </div>
              ) : (
                <div className="space-y-3">
                  {subjectForm.trabalhos.map((trabalho, index) => (
                    <Card key={index} className="p-4">
                      <div className="space-y-3">
                        <div className="flex justify-between items-start">
                          <h4 className="font-medium text-sm">Trabalho {index + 1}</h4>
                          <Button 
                            type="button"
                            variant="ghost" 
                            size="sm" 
                            className="text-red-500 h-6"
                            onClick={() => removeTrabalho(index)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                        
                        <div className="grid grid-cols-2 gap-3">
                          <div className="space-y-1">
                            <Label className="text-xs">Título *</Label>
                            <Input 
                              value={trabalho.titulo}
                              onChange={(e) => updateTrabalho(index, 'titulo', e.target.value)}
                              placeholder="Nome do trabalho"
                              className="h-9"
                            />
                          </div>
                          <div className="space-y-1">
                            <Label className="text-xs">Data de Entrega</Label>
                            <Input 
                              type="date"
                              value={trabalho.dataEntrega}
                              onChange={(e) => updateTrabalho(index, 'dataEntrega', e.target.value)}
                              className="h-9"
                            />
                          </div>
                        </div>

                        <div className="space-y-1">
                          <Label className="text-xs">Descrição</Label>
                          <Textarea 
                            value={trabalho.descricao}
                            onChange={(e) => updateTrabalho(index, 'descricao', e.target.value)}
                            placeholder="Descrição do trabalho (opcional)"
                            rows={2}
                            className="resize-none"
                          />
                        </div>

                        <div className="flex items-center space-x-2">
                          <Checkbox
                            id={`concluido-${index}`}
                            checked={trabalho.concluido}
                            onCheckedChange={(checked) => updateTrabalho(index, 'concluido', checked)}
                          />
                          <Label htmlFor={`concluido-${index}`} className="text-sm cursor-pointer">
                            Trabalho concluído
                          </Label>
                        </div>
                      </div>
                    </Card>
                  ))}
                </div>
              )}
            </div>
          </div>
          
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setSubjectModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveSubject}>
              <Save className="mr-2 h-4 w-4" />
              Salvar Matéria
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Anotação */}
      <Dialog open={noteModal} onOpenChange={setNoteModal}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>{editingNote ? "Editar Anotação" : "Nova Anotação"}</DialogTitle>
            <DialogDescription>
              Crie ou edite uma anotação de estudo
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Título *</Label>
              <Input 
                value={noteForm.titulo} 
                onChange={(e) => setNoteForm({...noteForm, titulo: e.target.value})}
                placeholder="Título da anotação"
              />
            </div>
            <div className="space-y-2">
              <Label>Matéria</Label>
              <Select 
                value={noteForm.materiaId} 
                onValueChange={(value) => setNoteForm({...noteForm, materiaId: value})}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione a matéria" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sem matéria</SelectItem>
                  {subjects.map((subject) => (
                    <SelectItem key={subject.id} value={subject.id.toString()}>
                      {subject.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Conteúdo *</Label>
              <Textarea 
                value={noteForm.conteudo} 
                onChange={(e) => setNoteForm({...noteForm, conteudo: e.target.value})}
                placeholder="Escreva sua anotação aqui..."
                rows={8}
              />
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setNoteModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveNote}>
              <Save className="mr-2 h-4 w-4" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}